+import { readFileSync, writeFileSync } from "fs";
+import { fileURLToPath } from "url";
+
+const pkgPath = fileURLToPath(new URL('./package.json', import.meta.url));
+
+const raw = readFileSync(pkgPath, "utf8");
+const pkg = JSON.parse(raw);
+
+const targets = {
+  ".": "./node_modules/@angular/common/types/common.d.ts",
+  "./http": "./node_modules/@angular/common/types/http.d.ts",
+  "./http/testing": "./node_modules/@angular/common/types/http-testing.d.ts",
+  "./testing": "./node_modules/@angular/common/types/testing.d.ts",
+  "./upgrade": "./node_modules/@angular/common/types/upgrade.d.ts",
+};
+
+const nextExports = {};
+for (const key of Object.keys(pkg.exports)) {
+  const value = pkg.exports[key];
+  const entry =
+    typeof value === "object" && value !== null && !Array.isArray(value) ? value : {};
+  const target = targets[key];
+  nextExports[key] = target ? { ...entry, types: target } : entry;
+}
+
+pkg.exports = nextExports;
+pkg.typings = targets["."];
+
+writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + "\n", "utf8");
+console.log(JSON.stringify({ ok: true, typings: pkg.typings }));
